<style>
.mv-reg-popup-backdrop{display:none;position:fixed;inset:0;z-index:9999;background:rgba(2,8,23,.8);backdrop-filter:blur(7px);align-items:center;justify-content:center;padding:20px}
.mv-reg-popup-backdrop.is-open{display:flex}
.mv-reg-popup{width:min(100%,440px);background:#131b2d;border:1px solid #44474e;border-radius:18px;padding:25px;color:#dae2fb;box-shadow:0 25px 80px #0009;animation:mvRegPop .18s ease-out}
.mv-reg-popup h3{font:700 22px/1.3 'Plus Jakarta Sans',sans-serif;margin:0 0 10px}
.mv-reg-popup p{color:#c5c6cf;line-height:1.6;margin:0 0 20px}
.mv-reg-popup button{padding:10px 16px;border-radius:9px;background:#0a458f;color:white;font-weight:600}
.mv-reg-popup .mv-reg-secondary{background:#2c3547}
@keyframes mvRegPop{from{opacity:0;transform:translateY(8px) scale(.98)}to{opacity:1;transform:translateY(0) scale(1)}}
</style>
<div class="mv-reg-popup-backdrop" id="registerPopup" role="dialog" aria-modal="true" aria-labelledby="registerPopupTitle">
 <div class="mv-reg-popup"><div style="font-size:24px;margin-bottom:12px" id="registerPopupIcon">✦</div><h3 id="registerPopupTitle">Informasi Registrasi</h3><p id="registerPopupMessage">Pesan registrasi</p>
 <div style="display:flex;justify-content:flex-end;gap:10px"><button type="button" class="mv-reg-secondary" id="registerPopupCancel">Batal</button><button type="button" id="registerPopupOk">Mengerti</button></div></div>
</div>

<script>
  // Popup Box 2: informasi dan konfirmasi registrasi
  const registerPopup = document.getElementById("registerPopup");
  function showRegisterPopup(title, message, confirmMode = false, onConfirm = null) {
    document.getElementById("registerPopupTitle").textContent = title;
    document.getElementById("registerPopupMessage").textContent = message;
    document.getElementById("registerPopupCancel").style.display = confirmMode ? "inline-block" : "none";
    document.getElementById("registerPopupOk").textContent = confirmMode ? "Ya, lanjutkan" : "Mengerti";
    registerPopup.classList.add("is-open");
    document.getElementById("registerPopupOk").onclick = () => { registerPopup.classList.remove("is-open"); if (confirmMode && onConfirm) onConfirm(); };
    document.getElementById("registerPopupCancel").onclick = () => registerPopup.classList.remove("is-open");
  }
  registerPopup.addEventListener("click", e => { if (e.target === registerPopup) registerPopup.classList.remove("is-open"); });

  function handleRegistrationSubmit() {
    const name = document.getElementById("fullName").value.trim();
    const contact = document.getElementById("emailPhone").value.trim();
    const pass = document.getElementById("password").value;
    const confirmPass = document.getElementById("confirmPassword").value;
    if (pass !== confirmPass) {
      showRegisterPopup("Kata sandi tidak cocok", "Pastikan kata sandi dan konfirmasi kata sandi sama.");
      return;
    }
    if (pass.length < 8) {
      showRegisterPopup("Kata sandi terlalu pendek", "Gunakan kata sandi minimal 8 karakter.");
      return;
    }
    showRegisterPopup("Konfirmasi pendaftaran", "Buat akun untuk " + name + " dengan kontak " + contact + "?", true, () => {
      showRegisterPopup("Pendaftaran berhasil", "Akun berhasil didaftarkan. Silakan masuk menggunakan email/nomor WhatsApp dan kata sandi Anda.");
      setTimeout(() => { registerPopup.classList.remove("is-open"); showLoginUserForm(); }, 1400);
    });
  }

  // Event 1: klik pada input kontak untuk memberi petunjuk
  document.getElementById("emailPhone").addEventListener("click", function () {
    this.title = "Masukkan email aktif atau nomor WhatsApp";
  });
  // Event 2: perubahan kata sandi memperbarui indikator kekuatan yang tersedia
  document.getElementById("password").addEventListener("change", function () {
    checkStrength(this.value);
  });
  // Event 3: submit formulir memvalidasi data dan memunculkan popup
  document.getElementById("registrationForm").addEventListener("submit", function (event) {
    event.preventDefault();
    handleRegistrationSubmit();
  });

  // Login user dan register berbagi satu halaman agar tidak ada file login_user.html terpisah.
  const registrationForm = document.getElementById("registrationForm");
  const userLoginForm = document.getElementById("userLoginForm");
  const registerTab = document.querySelector('#registrationForm').previousElementSibling;
  function showLoginUserForm() {
    registrationForm.style.display = "none"; userLoginForm.style.display = "block";
    document.querySelector(".w-full.max-w-xl.mx-auto.space-y-6 h2").textContent = "Masuk ke Akun Anda";
    document.querySelector(".w-full.max-w-xl.mx-auto.space-y-6 h2 + p").textContent = "Masuk untuk mengelola reservasi dan petualangan Anda.";
    document.getElementById("showUserLogin").classList.add("bg-primary-container","text-white");
    document.getElementById("showUserLogin").classList.remove("text-on-surface-variant");
  }
  function showRegisterForm() {
    userLoginForm.style.display = "none"; registrationForm.style.display = "block";
    document.querySelector(".w-full.max-w-xl.mx-auto.space-y-6 h2").textContent = "Buat Akun Baru";
    document.querySelector(".w-full.max-w-xl.mx-auto.space-y-6 h2 + p").textContent = "Daftar akun gratis dalam 1 menit untuk kelola reservasi dan rute petualangan Anda.";
    document.getElementById("showUserLogin").classList.remove("bg-primary-container","text-white");
    document.getElementById("showUserLogin").classList.add("text-on-surface-variant");
  }
  document.getElementById("showUserLogin").addEventListener("click", showLoginUserForm);
  document.getElementById("showRegister").addEventListener("click", showRegisterForm);
  userLoginForm.addEventListener("submit", function(event) {
    event.preventDefault();
    const contact = document.getElementById("userLoginContact").value.trim();
    const password = document.getElementById("userLoginPassword").value;
    if (!contact || !password) { showRegisterPopup("Data belum lengkap", "Masukkan email/nomor WhatsApp dan kata sandi."); return; }
    showRegisterPopup("Login berhasil", "Login berhasil. Anda akan diarahkan ke beranda MalangVenture.");
    setTimeout(() => { window.location.href = "index.php"; }, 1300);
  });

  function togglePass(inputId, iconId) {
    const input = document.getElementById(inputId);
    const icon = document.getElementById(iconId);
    if (!input || !icon) return;
    if (input.type === 'password') {
      input.type = 'text';
      icon.textContent = 'visibility_off';
    } else {
      input.type = 'password';
      icon.textContent = 'visibility';
    }
  }

  function checkStrength(val) {
    const b1 = document.getElementById('bar-1');
    const b2 = document.getElementById('bar-2');
    const b3 = document.getElementById('bar-3');
    const b4 = document.getElementById('bar-4');
    const label = document.getElementById('strength-text');
    if (!b1 || !b2 || !b3 || !b4 || !label) return;

    let score = 0;
    if (val.length >= 8) score++;
    if (/[A-Z]/.test(val)) score++;
    if (/[0-9]/.test(val)) score++;
    if (/[^A-Za-z0-9]/.test(val)) score++;

    [b1, b2, b3, b4].forEach(b => b.className = 'h-full w-1/4 bg-surface-container-highest transition-all duration-300');

    if (val.length === 0) {
      label.textContent = 'Belum dimasukkan';
      label.className = 'text-secondary font-semibold';
      return;
    }

    if (score === 1) {
      b1.classList.remove('bg-surface-container-highest');
      b1.classList.add('bg-error');
      label.textContent = 'Lemah';
      label.className = 'text-error font-semibold';
    } else if (score === 2) {
      b1.classList.remove('bg-surface-container-highest');
      b2.classList.remove('bg-surface-container-highest');
      b1.classList.add('bg-amber-400');
      b2.classList.add('bg-amber-400');
      label.textContent = 'Cukup';
      label.className = 'text-amber-400 font-semibold';
    } else if (score === 3) {
      b1.classList.remove('bg-surface-container-highest');
      b2.classList.remove('bg-surface-container-highest');
      b3.classList.remove('bg-surface-container-highest');
      b1.classList.add('bg-secondary');
      b2.classList.add('bg-secondary');
      b3.classList.add('bg-secondary');
      label.textContent = 'Kuat';
      label.className = 'text-secondary font-semibold';
    } else if (score >= 4) {
      [b1, b2, b3, b4].forEach(b => {
        b.classList.remove('bg-surface-container-highest');
        b.classList.add('bg-emerald-400');
      });
      label.textContent = 'Sangat Kuat';
      label.className = 'text-emerald-400 font-semibold';
    }
  }
</script></main>


<script>
// BAB 5 PHP: mengirim data form ke server dan menyimpan identitas pada PHP session.
document.addEventListener('submit', async function(e) {
  const form = e.target;
  if (!['registrationForm','userLoginForm','adminLoginForm'].includes(form.id)) return;
  e.preventDefault();
  e.stopImmediatePropagation();
  let payload = new URLSearchParams();
  if (form.id === 'registrationForm') {
    payload.set('action','register');
    payload.set('name', document.getElementById('fullName').value.trim());
    payload.set('contact', document.getElementById('emailPhone').value.trim());
    payload.set('password', document.getElementById('password').value);
    if (payload.get('password') !== document.getElementById('confirmPassword').value) {
      alert('Konfirmasi kata sandi tidak sama.'); return;
    }
    if (!form.querySelector('input[type="checkbox"]').checked) {
      alert('Centang persetujuan terlebih dahulu.'); return;
    }
  } else if (form.id === 'userLoginForm') {
    payload.set('action','login_user');
    payload.set('contact',document.getElementById('userLoginContact').value.trim());
    payload.set('password',document.getElementById('userLoginPassword').value);
  } else {
    payload.set('action','login_admin');
    payload.set('contact',document.getElementById('adminEmail').value.trim());
    payload.set('password',document.getElementById('adminPassword').value);
  }
  try {
    const response = await fetch('auth.php', {method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:payload.toString(),credentials:'same-origin'});
    const result = await response.json();
    if (!response.ok || !result.ok) { alert(result.message || 'Proses gagal.'); return; }
    alert(result.message);
    window.location.href = result.redirect;
  } catch (err) {
    alert('Tidak dapat menghubungi PHP. Jalankan project melalui Laragon/XAMPP, bukan file://.');
  }
}, true);
</script>

<script>
if (new URLSearchParams(window.location.search).get('mode') === 'login') {
  const rf = document.getElementById('registrationForm');
  const lf = document.getElementById('userLoginForm');
  if (rf && lf) { rf.style.display='none'; lf.style.display='block'; }
}
</script>
